CREATE FUNCTION cmd_validate_animal_skill_operation_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; op rule_animal_skill_operation%ROWTYPE; BEGIN SELECT * INTO STRICT op FROM rule_animal_skill_operation WHERE rule_id=NEW.operation_rule_id AND operation_code=NEW.operation_code; IF op.animal_subject_required<>(NEW.subject_animal_actor_id IS NOT NULL) AND op.animal_subject_required THEN RAISE EXCEPTION 'Animal subject is required'; END IF; SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>op.skill_rule_id OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Animal skill operation receipt does not match its task'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_animal_skill_operation_receipt_valid AFTER INSERT ON cmd_animal_skill_operation_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_animal_skill_operation_receipt();
